IF OBJECT_ID('dbo.CompraItens','U') IS NULL EXEC('CREATE TABLE dbo.CompraItens (Id int IDENTITY(1,1) NOT NULL PRIMARY KEY, CompraId int NOT NULL, ProdutoId int NOT NULL, Quantidade decimal(18,4) NOT NULL, PrecoUnitario decimal(18,2) NOT NULL, DescontoPercentual decimal(5,2) NOT NULL CONSTRAINT DF_CompraItens_Desc DEFAULT 0, IvaPercentual decimal(5,2) NOT NULL CONSTRAINT DF_CompraItens_Iva DEFAULT 0, Ativo bit NOT NULL CONSTRAINT DF_CompraItens_Ativo DEFAULT 1, DataCriacao datetime2 NOT NULL CONSTRAINT DF_CompraItens_DC DEFAULT SYSUTCDATETIME(), DataAtualizacao datetime2 NULL, CONSTRAINT FK_CompraItens_Compra FOREIGN KEY(CompraId) REFERENCES dbo.Compras(Id) ON DELETE CASCADE, CONSTRAINT FK_CompraItens_Produto FOREIGN KEY(ProdutoId) REFERENCES dbo.Produtos(Id));');
IF OBJECT_ID('dbo.VendaItens','U') IS NULL EXEC('CREATE TABLE dbo.VendaItens (Id int IDENTITY(1,1) NOT NULL PRIMARY KEY, ContaReceberId int NOT NULL, ProdutoId int NOT NULL, Quantidade decimal(18,4) NOT NULL, PrecoUnitario decimal(18,2) NOT NULL, DescontoPercentual decimal(5,2) NOT NULL CONSTRAINT DF_VendaItens_Desc DEFAULT 0, IvaPercentual decimal(5,2) NOT NULL CONSTRAINT DF_VendaItens_Iva DEFAULT 0, Ativo bit NOT NULL CONSTRAINT DF_VendaItens_Ativo DEFAULT 1, DataCriacao datetime2 NOT NULL CONSTRAINT DF_VendaItens_DC DEFAULT SYSUTCDATETIME(), DataAtualizacao datetime2 NULL, CONSTRAINT FK_VendaItens_Conta FOREIGN KEY(ContaReceberId) REFERENCES dbo.ContasReceber(Id) ON DELETE CASCADE, CONSTRAINT FK_VendaItens_Produto FOREIGN KEY(ProdutoId) REFERENCES dbo.Produtos(Id));');
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_CompraItens_CompraId_ProdutoId') CREATE INDEX IX_CompraItens_CompraId_ProdutoId ON dbo.CompraItens(CompraId,ProdutoId);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_VendaItens_ContaReceberId_ProdutoId') CREATE INDEX IX_VendaItens_ContaReceberId_ProdutoId ON dbo.VendaItens(ContaReceberId,ProdutoId);
